        base_ = mkdtemp(tpl);
        ASSERT_FALSE(base_.empty());
    }
    void TearDown() override {
        if (!base_.empty()) {
            std::string cmd = "rm -rf '" + base_ + "'";
            ASSERT_EQ(std::system(cmd.c_str()), 0);
