39	 *
40	 * 管理与 WeakNet 服务端的 D-Bus 连接，提供方法调用和信号订阅能力。
41	 * 此类被包装为 C API（weaknet_* 函数）对外暴露，
42	 * 外部程序不应直接使用此类。
43	 */
44	class WeakNetClient {
45	private:
46	    DBusConnection* conn_;    ///< D-Bus 系统总线连接句柄
47	    bool connected_;          ///< 连接状态标记
48	
49	    /**
50	     * @brief 初始化 D-Bus 连接（系统总线）
51	     *
52	     * 调用 dbus_bus_get(DBUS_BUS_SYSTEM, ...) 连接到系统总线。
53	     * 服务端以 root 系统服务运行并注册在系统总线（/etc/dbus-1/system.d/
54	     * 中的 com.example.WeakNet.conf 策略允许本地用户访问），客户端与服务端
55	     * 必须使用同一条总线。
56	     * 连接失败时记录日志并将 connected_ 置为 false。
57	     *
58	     * @return true  - 连接成功
59	     * @return false - 连接失败
60	     */
61	    bool initConnection() {
