void EdgeTelemetryExporter::queueActionResult(const std::string& action_id, const char* status,
                                               const std::string& detail,
                                               const std::string& claim_token,
                                               uint64_t generation,
                                               const std::string& config_key,
                                               const std::string& config_value) {
    EdgeActionResultRecord rec;
    rec.action_id = action_id;
    rec.status = status;
    rec.detail = detail;

    const auto now_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::system_clock::now().time_since_epoch()).count();

    std::ostringstream body;
    body << "{\"schema_version\":\"network.edge.action-results.v2\",";
    body << "\"device_id\":\"" << weaknet_utils::escapeJsonString(config_.edge.device_id.get()) << "\",";
    body << "\"results\":[{";
    body << "\"action_id\":\"" << weaknet_utils::escapeJsonString(action_id) << "\",";
    body << "\"status\":\"" << rec.status << "\",";
    body << "\"detail\":\"" << weaknet_utils::escapeJsonString(detail) << "\",";
    body << "\"claim_token\":\"" << weaknet_utils::escapeJsonString(claim_token) << "\",";
    body << "\"generation\":" << generation << ",";
    // 仅本地变更携带：云端下发的动作由服务端从 network_pending_actions 回读
    // key/value，两处来源同时写会互相打架。空串 = 不写该字段。
    if (!config_key.empty()) {
        body << "\"config_key\":\"" << weaknet_utils::escapeJsonString(config_key) << "\",";
        body << "\"config_value\":\"" << weaknet_utils::escapeJsonString(config_value) << "\",";
    }
    body << "\"reported_at\":\"" << formatRfc3339Utc(now_ms) << "\"}]}";
    rec.body = body.str();

    std::string sign_error;
    rec.signature = signBody(rec.body, &sign_error);
    if (rec.signature.empty()) {
        LOG_ERROR(weaknet_dbus::LogModule::SYSTEM,
                  "动作结果签名失败，无法回执: action=" << action_id << " (" << sign_error << ")");
        return;
    }

    {
        std::lock_guard<std::mutex> lock(mutex_);
        pending_action_results_.push_back(std::move(rec));
    }
    cv_.notify_one();
}

void EdgeTelemetryExporter::emitLocalConfigChange(const std::string& key,
                                                  const std::string& value,
                                                  const std::string& detail,
                                                  uint32_t config_generation) {
    // 契约上限（与 service 端 NetworkPendingActionRecord 的 String(128)/
    // String(512) 对齐）。超限的**整批** action-results 会被 422 拒掉，把
    // 同批其它回执一起拖下水，所以宁可本端截断也不能让上游拒收。
    static constexpr size_t kMaxKey = 128;
    static constexpr size_t kMaxValue = 512;
    std::string key_c = key.substr(0, kMaxKey);
    std::string value_c = value.substr(0, kMaxValue);
    if (key.size() > kMaxKey || value.size() > kMaxValue) {
        LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
                    "本地调参回执超契约长度已截断: key=" << key_c
                    << " (key_len=" << key.size() << " value_len=" << value.size() << ")");
    }

    queueActionResult("nlocal-" + randomHex16(), "APPLIED", detail, "",
                      config_generation, key_c, value_c);
}

bool EdgeTelemetryExporter::tickWatchdog(std::chrono::steady_clock::time_point now) const {
    return config_txn_ && config_txn_->deadlineExpired(now);
}

bool EdgeTelemetryExporter::evaluateTrialDeadline(const AssessmentSnapshot* latest_snapshot) {
    if (!config_txn_) return false;
    if (!tickWatchdog(std::chrono::steady_clock::now())) return false;

    const auto trial = config_txn_->trial();
    const auto generation = trial.generation;

    // fail-safe：没有可用快照也按"未知健康"回滚，不赌设备状态。
    if (!latest_snapshot) {
        auto* cfg = const_cast<weaknet_dbus::WeakNetConfig*>(&config_);
        const std::string reason = "watchdog_timeout_no_snapshot";
        if (config_txn_->forceRollback(cfg, reason)) {
            LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
                        "TRIAL 看门狗超时 + 无快照 → 已回滚到 prior_values");
            emitRollbackReceipt(reason);
        }
        return true;
    }

    const auto overall = latest_snapshot->experience.overall;
    const auto reach = latest_snapshot->experience.ip_reachability.state;
    // S7：确认条件收紧——只有 overall 明确 GOOD 才算健康。旧判据
    // "overall != BAD" 会把 UNKNOWN/DEGRADED 也当健康直接 confirmStable，
    // 等于让"评估器没看懂"替配置变更背书。
    const bool healthy = (overall == weaknet::HealthState::GOOD) &&
                         (reach != weaknet::HealthState::BAD);

    if (healthy) {
        std::string err;
        if (config_txn_->confirmStable(generation, &err)) {
            LOG_INFO(weaknet_dbus::LogModule::SYSTEM,
                     "TRIAL 看门狗超时 + 健康评估通过 → 已确认 STABLE (gen=" << generation << ")");
            return true;
        }
        LOG_ERROR(weaknet_dbus::LogModule::SYSTEM,
                  "confirmStable 失败: " << err);
        return false;
    }

    auto* cfg = const_cast<weaknet_dbus::WeakNetConfig*>(&config_);

    // 证据不足（UNKNOWN）≠ 证据不利：不确认也不立即回滚，延长一次窗口
    // （至 2× deadline）再观察；延长配额耗尽仍非 GOOD → 下方保守回滚。
    const bool unknown = overall == weaknet::HealthState::UNKNOWN ||
                         reach == weaknet::HealthState::UNKNOWN;
    if (unknown && config_txn_->extendDeadline()) {
        LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
                    "TRIAL 看门狗超时 + 健康 UNKNOWN → 延长试用窗口一次 (gen="
                        << generation << ", overall="
                        << weaknet::healthStateToString(overall)
                        << ", ip_reachability="
                        << weaknet::healthStateToString(reach) << ")");
        return false;
    }

    const std::string reason = unknown ? "watchdog_timeout_health_unknown"
                                       : "watchdog_timeout_health_bad";
    if (config_txn_->forceRollback(cfg, reason)) {
        LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
                    "TRIAL 看门狗超时 + 非 GOOD → 已回滚 (overall=" << static_cast<int>(overall)
                    << " ip_reachability=" << static_cast<int>(reach) << ")");
        emitRollbackReceipt(reason);
        return true;
    }
    return false;
}

void EdgeTelemetryExporter::emitRollbackReceipt(const std::string& reason) {
    // ROLLBACK 回执：优先绑定触发本 trial 的云端 action_id，
    // 使服务端把该动作记为终态 ROLLBACK；拿不到（异常路径）时退回
    // sentinel 形式——sentinel 不在 network_pending_actions 中，服务端会
    // 丢弃，但本地日志仍保留回滚事实。
    const auto trial = config_txn_ ? config_txn_->trial() : weaknet_dbus::TrialWindow{};
    const std::string& action_id = !trial.pending_action_id.empty()
        ? trial.pending_action_id
        : ("watchdog-" + std::to_string(
              std::chrono::duration_cast<std::chrono::milliseconds>(
                  std::chrono::system_clock::now().time_since_epoch()).count()));
    queueActionResult(action_id, "ROLLBACK", reason, "",
                      config_txn_ ? config_txn_->lastAppliedGeneration() : 0);
}

std::string EdgeTelemetryExporter::actionResultsUrl() const {
    std::string url = config_.edge.url.get();
    const std::string suffix = "/telemetry";
    if (url.size() >= suffix.size() &&
        url.compare(url.size() - suffix.size(), suffix.size(), suffix) == 0) {
        url.replace(url.size() - suffix.size(), suffix.size(), "/action-results");
    } else {
        // URL 形态不符约定时显式失败，而不是把结果发到一个错误的端点。
        url.clear();
    }
    return url;
}

bool EdgeTelemetryExporter::transmitActionResults(std::string* error) {
    std::deque<EdgeActionResultRecord> pending;
    {
        std::lock_guard<std::mutex> lock(mutex_);
        pending.swap(pending_action_results_);

toolUseResult.stdout:
        // 无论应用成功与否都必须回执：服务端靠它把 action 推进到
        // APPLIED/REJECTED，缺了回执这条 action 会停在 DELIVERED 永远不完结。
        queueActionResult(action.action_id, ok ? "APPLIED" : "REJECTED",
                          ok ? "applied" : error,
                          action.claim_token, action.generation);
    }
}

