    ASSERT_EQ(recs.size(), 1u);
    EXPECT_EQ(recs[0].status, "APPLIED");
    EXPECT_EQ(recs[0].action_id, "nact-ota-unittest");
    // detail 必须携带真实安装版本（云端据此核对是否真的升级了）
