#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""weaknet-ota-ctl — OTA 升级事务控制器（P0-A）

================================================================================
为什么需要这个程序
================================================================================

升级可靠性不能建立在"被升级的服务自己"之上。原实现里，`current` 指针、
`.previous` 回滚指针、`.committed` 转正标记由多个执行路径各自读写
（`cmd_apply` / `cmd_rollback` / `cmd_adopt` / legacy 迁移 / `--commit`），
一旦升级进程在关键窗口被掉电或杀死，**没有任何一方知道这次升级做到哪一步**。

本控制器把三件事收口到一处：

  1. 唯一的持久化事实来源：`/var/lib/weaknet-ota/transaction.json`
  2. 唯一的版本指针写入口：`current` / `.previous` / `.committed` 只由本程序改
  3. 可判定的恢复语义：每个崩溃点都能从 (事务状态, current 真实指向) 推出
     唯一且非破坏性的下一步

P0-A 只解决"可观察、可判定、可显式修复"。**开机自动恢复属于 P0-B**，
本程序提供 `reconcile --dry-run` 供其调用，但自身不在开机时自动执行任何
破坏性动作。

================================================================================
关键设计约束
================================================================================

* **不随 OTA 制品升级**：本文件必须放在 $ROOT 之外（默认 `/usr/local/lib/`），
  绝不能被 `install_self_script` 或 release 包覆盖。理由：事务 schema 由它写入，
  若它随版本变化，则旧版恢复服务可能读到新版 schema。
* **原子落盘**：写文件用 temp + fsync + rename + fsync(dir)；翻软链用
  symlink + rename + fsync(dir)。仅 `rename` 原子是不够的，目录项也必须落盘。
* **单一写者**：所有状态变更走同一把 flock 互斥锁；冲突立即失败，不排队。
* **fail-closed**：schema 不认识、phase 不认识、指针指向不在版本集合内的值、
  JSON 损坏 —— 一律不做破坏性动作，转 RECOVERY_REQUIRED 或拒绝执行。

================================================================================
物理持久性说明（重要）
================================================================================

`fsync` 保证的是「内核 → 设备」的持久化语义，**不保证**设备写缓存里的数据
已落到介质。开发板实测根分区在 `/dev/sda3`（SATA/USB 盘），若该盘启用写缓存
且未走 FUA，掉电仍可能丢失已 fsync 的数据。因此本程序的持久化顺序是**必要
不充分**条件——真正的断电安全必须由真机掉电测试确认，不能用 `kill -9` 代替。
"""

import argparse
import errno
import fcntl
import json
import os
import re
import shutil
import subprocess
import sys
import time

SCHEMA_VERSION = 1

# ---- 阶段枚举（严格封闭：未知值一律 fail-closed）--------------------------------
PHASE_PREPARED = "PREPARED"
PHASE_SWITCH_PENDING = "SWITCH_PENDING"
PHASE_TRIAL = "TRIAL"
PHASE_COMMITTED = "COMMITTED"
PHASE_FORCED_COMMITTED = "FORCED_COMMITTED"   # --commit 人工跳过健康验证
PHASE_ABORTED = "ABORTED"
PHASE_ROLLBACK_PENDING = "ROLLBACK_PENDING"
PHASE_ROLLBACK_VERIFY = "ROLLBACK_VERIFY"
PHASE_ROLLED_BACK = "ROLLED_BACK"
PHASE_RECOVERY_REQUIRED = "RECOVERY_REQUIRED"

ALL_PHASES = frozenset({
    PHASE_PREPARED, PHASE_SWITCH_PENDING, PHASE_TRIAL,
    PHASE_COMMITTED, PHASE_FORCED_COMMITTED, PHASE_ABORTED,
    PHASE_ROLLBACK_PENDING, PHASE_ROLLBACK_VERIFY, PHASE_ROLLED_BACK,
    PHASE_RECOVERY_REQUIRED,
})

# 终态：接受下一笔事务前会先归档到 history/
TERMINAL_PHASES = frozenset({
    PHASE_COMMITTED, PHASE_FORCED_COMMITTED, PHASE_ABORTED, PHASE_ROLLED_BACK,
})

# 非终态：掉电后必须继续处理，绝不能误标成已回滚/已成功
LIVE_PHASES = frozenset({
    PHASE_PREPARED, PHASE_SWITCH_PENDING, PHASE_TRIAL,
    PHASE_ROLLBACK_PENDING, PHASE_ROLLBACK_VERIFY,
})

VERSION_RE = re.compile(r"^[0-9]+\.[0-9]+\.[0-9]+$")

# 退出码（供上层脚本与测试断言）
EXIT_OK = 0
EXIT_ERROR = 1
EXIT_USAGE = 2
EXIT_CONFLICT = 3        # 非法状态转换 / 并发冲突
EXIT_RECOVERY = 4        # 需要人工介入
EXIT_SCHEMA = 5          # schema 不兼容或数据损坏


class OtaError(Exception):
    def __init__(self, message, code=EXIT_ERROR):
        super().__init__(message)
        self.code = code


class ConflictError(OtaError):
    def __init__(self, message):
        super().__init__(message, EXIT_CONFLICT)


class SchemaError(OtaError):
    def __init__(self, message):
        super().__init__(message, EXIT_SCHEMA)


# ============================================================================
# 路径解析
# ============================================================================

def resolve_paths(root=None, state_dir=None):
    """返回 (root, state_dir)。

    root 默认 /home/radxa/weaknet（可用 WEAKNET_ROOT 覆盖，与升级脚本一致）；
    state_dir 默认 /var/lib/weaknet-ota（可用 WEAKNET_OTA_STATE_DIR 覆盖）。

    注意 state_dir 与 root 在开发板上同属根分区——它们提供的是**生命周期与
    权限隔离**（不随 release 切换、0600 且仅 root 可写），不是物理隔离。
    """
    root = root or os.environ.get("WEAKNET_ROOT") or "/home/radxa/weaknet"
    state_dir = state_dir or os.environ.get("WEAKNET_OTA_STATE_DIR") or "/var/lib/weaknet-ota"
    return os.path.abspath(root), os.path.abspath(state_dir)


# ============================================================================
# 原子 IO
# ============================================================================

def fsync_dir(path):
    """fsync 一个目录，确保其中的目录项（rename/symlink）真正落盘。

    只 fsync 文件是不够的：rename 改变了父目录的目录项，父目录本身不 fsync
    的话，掉电后可能看到"旧文件名还在"或"两个都在"。
    """
    fd = os.open(path, os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def atomic_write_bytes(path, payload, mode=0o600):
    """temp(同目录) → 写入 → fsync → rename → fsync(dir)。

    任何一步失败都抛异常，调用方不得据此宣称状态转换成功。
    """
    directory = os.path.dirname(path) or "."
    os.makedirs(directory, exist_ok=True)
    tmp = "%s.tmp.%d" % (path, os.getpid())

    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, mode)
    try:
        os.write(fd, payload)
        os.fsync(fd)
    finally:
        os.close(fd)

    os.replace(tmp, path)
    fsync_dir(directory)


def atomic_write_json(path, obj):
    payload = (json.dumps(obj, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode("utf-8")
    atomic_write_bytes(path, payload)


def atomic_symlink(target, linkpath):
    """symlink + rename 原子替换。target 是相对路径（如 releases/1.2.0）。

    必须沿用相对路径 —— 现有 `current` 就是 `releases/<ver>` 形式，
    `weaknet-cli`、C++ 服务端、以及运维脚本都可能依赖这一形态。
    """
    directory = os.path.dirname(linkpath) or "."
    tmp = "%s.tmp.%d" % (linkpath, os.getpid())
    if os.path.lexists(tmp):
        os.unlink(tmp)
    os.symlink(target, tmp)
    os.rename(tmp, linkpath)   # rename(2) 覆盖已有软链是原子的
    fsync_dir(directory)


# ============================================================================
# 互斥锁
# ============================================================================

class ExclusiveLock(object):
    """同一时刻只允许一个写者。非阻塞：拿不到锁立即失败。"""

    def __init__(self, state_dir):
        self.path = os.path.join(state_dir, "lock")
        self.fd = None

    def __enter__(self):
        os.makedirs(os.path.dirname(self.path), exist_ok=True)
        self.fd = os.open(self.path, os.O_RDWR | os.O_CREAT, 0o600)
        try:
            fcntl.flock(self.fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError as exc:
            os.close(self.fd)
            self.fd = None
            if exc.errno in (errno.EACCES, errno.EAGAIN):
                raise ConflictError("另一个 OTA 事务正在进行（%s 已被占用）" % self.path)
            raise
        return self

    def __exit__(self, *exc_info):
        if self.fd is not None:
            try:
                fcntl.flock(self.fd, fcntl.LOCK_UN)
            finally:
                os.close(self.fd)
                self.fd = None
        return False


# ============================================================================
# 版本与指针
# ============================================================================

def check_version(value, field="version"):
    if not isinstance(value, str) or not VERSION_RE.match(value):
        raise OtaError("%s 非法：%r（需 X.Y.Z，且不得含路径分隔符）" % (field, value), EXIT_USAGE)
    return value


def read_current(root):
    """读取 current 软链指向的版本号；不存在或形态异常返回 None。

    现有布局：current -> releases/<ver>（相对路径）。这里只取末段，
    同时对绝对路径（历史残留）保持兼容，但**不会**接受指向 releases/ 之外的值。
    """
    link = os.path.join(root, "current")
    if not os.path.islink(link):
        return None
    target = os.readlink(link)
    name = os.path.basename(target.rstrip("/"))
    if not VERSION_RE.match(name):
        return None
    return name


def release_dir(root, version):
    return os.path.join(root, "releases", version)


def release_exists(root, version):
    return os.path.isdir(release_dir(root, version))


def list_versions(root):
    releases = os.path.join(root, "releases")
    if not os.path.isdir(releases):
        return []
    out = []
    for name in os.listdir(releases):
        if VERSION_RE.match(name) and os.path.isdir(os.path.join(releases, name)):
            out.append(name)
    return sorted(out, key=version_key)


def version_key(v):
    return tuple(int(x) for x in v.split("."))


# ============================================================================
# 事务状态
# ============================================================================

def empty_state():
    return {
        "schema_version": SCHEMA_VERSION,
        "revision": 0,
        "stable_version": None,
        "previous_stable_version": None,
        "transaction": None,
    }


def state_path(state_dir):
    return os.path.join(state_dir, "transaction.json")


def load_state(state_dir):
    """读取并严格校验事务状态。缺失 = 全新设备，返回空状态。"""
    path = state_path(state_dir)
    try:
        with open(path, "r", encoding="utf-8") as fh:
            raw = fh.read()
    except IOError as exc:
        if exc.errno == errno.ENOENT:
            return empty_state()
        raise

    try:
        data = json.loads(raw)
    except ValueError as exc:
        raise SchemaError("事务状态文件损坏，无法解析 JSON：%s" % exc)

    if not isinstance(data, dict):
        raise SchemaError("事务状态根节点必须是对象")

    schema = data.get("schema_version")
    if schema != SCHEMA_VERSION:
        # 不认识就 fail-closed：绝不猜测新版本语义
        raise SchemaError(
            "事务状态 schema_version=%r 不受支持（本程序只认 %d）；拒绝执行任何动作"
            % (schema, SCHEMA_VERSION))

    for field in ("revision",):
        if not isinstance(data.get(field), int):
            raise SchemaError("字段 %s 缺失或类型错误" % field)

    for field in ("stable_version", "previous_stable_version"):
        value = data.get(field)
        if value is not None:
            check_version(value, field)

    tx = data.get("transaction")
    if tx is not None:
        if not isinstance(tx, dict):
            raise SchemaError("transaction 必须是对象或 null")
        phase = tx.get("phase")
        if phase not in ALL_PHASES:
            raise SchemaError("未知 phase=%r —— 拒绝在无法判定的状态下执行动作" % (phase,))
        for field in ("from_version", "to_version", "rollback_target"):
            check_version(tx.get(field), "transaction." + field)
        if tx.get("previous_stable_before") is not None:
            check_version(tx["previous_stable_before"], "transaction.previous_stable_before")
        if not isinstance(tx.get("boot_attempts"), int):
            raise SchemaError("transaction.boot_attempts 缺失或类型错误")

    return data


def save_state(state_dir, state):
    """落盘并递增 revision。这是唯一的状态写入口。"""
    state["revision"] = int(state.get("revision", 0)) + 1
    atomic_write_json(state_path(state_dir), state)
    return state


def tx_of(state):
    return state.get("transaction")


def require_tx(state, *allowed_phases):
    tx = tx_of(state)
    if tx is None:
        raise ConflictError("当前没有进行中的事务")
    phase = tx["phase"]
    if phase not in allowed_phases:
        raise ConflictError(
            "当前阶段 %s 不允许该操作（要求：%s）" % (phase, ", ".join(sorted(allowed_phases))))
    return tx


# ============================================================================
# 兼容投影：.committed 与 .previous
# ============================================================================

def project_views(root, state):
    """把权威状态投影到历史兼容视图。

    * `releases/<ver>/.committed` —— C++ `update_status.cpp` 仍以它的存在判断
      `current_committed`，在 C++ 读路径改造并端到端验证之前不能删。
    * `.previous` —— 降级为派生视图，表示"上一稳定版本"，供 GC 白名单与
      旧 `rollback`（无 --to）读取。权威值来自状态文件。

    投影失败不抛异常：它属于兼容层，不能因为投影失败就把权威状态判成失败。
    """
    warnings = []

    stable = state.get("stable_version")
    if stable and release_exists(root, stable):
        marker = os.path.join(release_dir(root, stable), ".committed")
        if not os.path.exists(marker):
            try:
                atomic_write_bytes(marker, b"", mode=0o644)
            except OSError as exc:
                warnings.append("补写 .committed 失败：%s" % exc)

    prev = state.get("previous_stable_version")
    prev_file = os.path.join(root, "releases", ".previous")
    try:
        if prev:
            atomic_write_bytes(prev_file, (prev + "\n").encode("utf-8"), mode=0o644)
        elif os.path.exists(prev_file):
            os.unlink(prev_file)
            fsync_dir(os.path.dirname(prev_file))
    except OSError as exc:
        warnings.append("刷新 .previous 失败：%s" % exc)

    return warnings


# ============================================================================
# GC
# ============================================================================

def collect_garbage(root, state, max_keep):
    """保守 GC：只在权威状态合法且处于终态时运行。

    保护集合：current、stable、previous_stable、当前事务引用的全部版本。
    任何异常（非终态、RECOVERY_REQUIRED、记录不可解析）都整体跳过——
    GC 不是关键路径，多占几 MB 远比删掉回滚证据安全。
    """
    tx = tx_of(state)
    if tx is not None and tx["phase"] not in TERMINAL_PHASES:
        return [], "事务处于非终态（%s），整体跳过 GC" % tx["phase"]
    if tx is not None and tx["phase"] == PHASE_RECOVERY_REQUIRED:
        return [], "事务处于 RECOVERY_REQUIRED，整体跳过 GC"

    protected = set()
    cur = read_current(root)
    if cur:
        protected.add(cur)
    for field in ("stable_version", "previous_stable_version"):
        if state.get(field):
            protected.add(state[field])
    if tx:
        for field in ("from_version", "to_version", "rollback_target"):
            if tx.get(field):
                protected.add(tx[field])
        if tx.get("previous_stable_before"):
            protected.add(tx["previous_stable_before"])

    versions = list_versions(root)
    if len(versions) <= max_keep:
        return [], None

    removed = []
    keep_count = 0
    for ver in sorted(versions, key=version_key, reverse=True):
        if ver in protected:
            continue
        keep_count += 1
        if keep_count >= max_keep:
            path = release_dir(root, ver)
            shutil.rmtree(path, ignore_errors=True)
            removed.append(ver)
    return removed, None


# ============================================================================
# 状态机动作
# ============================================================================

def new_transaction(kind, from_version, to_version, rollback_target,
                    previous_stable_before, policy=None):
    return {
        "transaction_id": time.strftime("%Y%m%dT%H%M%SZ", time.gmtime()) + "-%d" % os.getpid(),
        "kind": kind,
        "phase": PHASE_PREPARED,
        "from_version": from_version,
        "to_version": to_version,
        "rollback_target": rollback_target,
        "previous_stable_before": previous_stable_before,
        "boot_attempts": 0,
        "last_trial_boot_id": "",
        "policy": policy or {},
        "started_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "updated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "last_error": "",
    }


def set_phase(state, phase, error=None):
    tx = state["transaction"]
    tx["phase"] = phase
    tx["updated_at"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    if error is not None:
        tx["last_error"] = error


def archive_transaction(state_dir, state):
    """终态事务在接受下一笔事务前归档。归档失败不得静默覆盖历史。"""
    tx = state.get("transaction")
    if not tx or tx["phase"] not in TERMINAL_PHASES:
        return None
    hist_dir = os.path.join(state_dir, "history")
    os.makedirs(hist_dir, exist_ok=True)
    name = "%s-%s.json" % (tx["transaction_id"], tx["phase"])
    path = os.path.join(hist_dir, name)
    atomic_write_json(path, tx)
    return path


# ============================================================================
# 指针切换（唯一入口）
# ============================================================================

COMPAT_ENTRIES = ("server", "client", "lib",
                  "edge_network_rag.py", "network_knowledge_base.py")


def refresh_compat_links(root):
    """current 翻转后维护兼容软链：$ROOT/{server,client,...} -> current/<name>。

    与 shell 版语义一致：目标真实存在才建链；$ROOT 下同名真目录（旧扁平布局
    残留）跳过，不擅自删除。
    """
    warnings = []
    current_link = os.path.join(root, "current")
    for entry in COMPAT_ENTRIES:
        src = os.path.join(current_link, entry)
        if not os.path.exists(src):
            continue
        dst = os.path.join(root, entry)
        if os.path.exists(dst) and not os.path.islink(dst):
            warnings.append("跳过兼容软链 %s：%s 是真实目录（旧布局残留）" % (entry, dst))
            continue
        atomic_symlink("current/" + entry, dst)
    return warnings


def switch_current(root, version):
    """把 current 原子指向 releases/<version>，并刷新兼容软链。

    幂等：已指向目标时直接返回，不重复翻转。指向第三版本视为状态异常，
    由调用方（reconcile）判定，本函数不做猜测。
    """
    if not release_exists(root, version):
        raise OtaError("目标版本不存在：releases/%s" % version, EXIT_USAGE)
    link = os.path.join(root, "current")
    cur = read_current(root)
    if cur == version:
        return False
    atomic_symlink("releases/" + version, link)
    return True


# ============================================================================
# reconcile：崩溃点恢复判定
# ============================================================================

def reconcile(root, state):
    """根据 (事务阶段, current 真实指向) 推出唯一的下一步。

    **不做任何破坏性动作**，只返回判定结果。P0-A 要求它可被 dry-run 调用；
    P0-B 的恢复服务将执行其中标为安全的动作。

    返回值字典：
      action: none|abort|mark_trial|continue_trial|continue_rollback|
              mark_rolled_back|project_views|recovery_required
      destructive: 该动作是否修改指针（P0-A 的 dry-run 永远不执行）
    """
    tx = tx_of(state)
    cur = read_current(root)

    def result(action, reason, destructive=False):
        return {"action": action, "reason": reason,
                "destructive": destructive, "current": cur,
                "phase": tx["phase"] if tx else None}

    if tx is None:
        return result("none", "没有进行中的事务")

    phase = tx["phase"]
    to_ver = tx["to_version"]
    from_ver = tx["from_version"]
    rollback_target = tx["rollback_target"]

    if phase in TERMINAL_PHASES:
        # 终态但投影可能滞后（例如 COMMITTED 落盘后、.committed 未补写时掉电）
        if phase in (PHASE_COMMITTED, PHASE_FORCED_COMMITTED) and cur == to_ver:
            marker = os.path.join(release_dir(root, cur), ".committed")
            if not os.path.exists(marker):
                return result("project_views", "已提交但兼容投影滞后，补写 .committed")
        return result("none", "事务已结束（%s）" % phase)

    if phase == PHASE_RECOVERY_REQUIRED:
        return result("recovery_required", "需要人工介入，禁止任何自动动作")

    if phase == PHASE_PREPARED:
        if cur == from_ver:
            return result("abort", "准备阶段未切换指针，保守取消", destructive=True)
        return result("recovery_required",
                      "PREPARED 阶段但 current 已非原版本（%r），状态不可信" % cur)

    if phase == PHASE_SWITCH_PENDING:
        # SWITCH_PENDING 的语义是「切换意图已落盘，指针可能还没翻」
        if cur == from_ver:
            return result("abort", "意图已落盘但指针未翻转，保守取消", destructive=True)
        if cur == to_ver:
            return result("mark_trial", "指针已翻转但未标记试运行，推进到 TRIAL",
                          destructive=True)
        return result("recovery_required",
                      "current 指向第三版本（%r），既非 %s 也非 %s" % (cur, from_ver, to_ver))

    if phase == PHASE_TRIAL:
        if cur == to_ver:
            return result("continue_trial", "试运行进行中，继续健康验证")
        return result("recovery_required",
                      "TRIAL 但 current 不再指向候选版本（%r），指针被外力改动" % cur)

    if phase == PHASE_ROLLBACK_PENDING:
        if cur == to_ver:
            return result("continue_rollback", "回滚意图已落盘但指针未翻，继续回滚",
                          destructive=True)
        if cur == rollback_target:
            return result("continue_rollback", "指针已回滚但未进入验证，推进到 ROLLBACK_VERIFY",
                          destructive=True)
        return result("recovery_required",
                      "回滚中 current 指向第三版本（%r），状态不可信" % cur)

    if phase == PHASE_ROLLBACK_VERIFY:
        if cur == rollback_target:
            return result("continue_trial", "回滚目标已就位，继续验证旧版健康")
        return result("recovery_required",
                      "回滚验证中 current 非回滚目标（%r）" % cur)

    return result("recovery_required", "未覆盖的 phase=%r" % phase)


# ============================================================================
# 命令实现
# ============================================================================

def cmd_status(args, root, state_dir):
    state = load_state(state_dir)
    tx = tx_of(state)
    payload = {
        "schema_version": state["schema_version"],
        "revision": state["revision"],
        "stable_version": state.get("stable_version"),
        "previous_stable_version": state.get("previous_stable_version"),
        "current": read_current(root),
        "phase": tx["phase"] if tx else None,
        "transaction_id": tx["transaction_id"] if tx else None,
        "release_count": len(list_versions(root)),
    }
    if tx:
        payload.update({
            "kind": tx.get("kind"),
            "from_version": tx.get("from_version"),
            "to_version": tx.get("to_version"),
            "rollback_target": tx.get("rollback_target"),
            "boot_attempts": tx.get("boot_attempts"),
            "last_error": tx.get("last_error"),
        })
    print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
    return EXIT_OK


def cmd_begin(args, root, state_dir):
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        tx = tx_of(state)
        if tx and tx["phase"] not in TERMINAL_PHASES:
            raise ConflictError("已有进行中的事务（%s），拒绝开始新事务" % tx["phase"])
        if tx:
            archive_transaction(state_dir, state)

        to_ver = check_version(args.to_version, "--to")
        from_ver = check_version(args.from_version, "--from")
        rollback_to = check_version(args.rollback_target, "--rollback-target")
        if not release_exists(root, to_ver):
            raise OtaError("目标版本不存在：releases/%s" % to_ver, EXIT_USAGE)
        if not release_exists(root, rollback_to):
            raise OtaError("回滚目标不存在：releases/%s" % rollback_to, EXIT_USAGE)
        # 失败候选不得成为回滚目标
        if rollback_to == to_ver:
            raise OtaError("回滚目标不能等于目标版本（失败版本不得成为稳定版本）", EXIT_USAGE)

        state["transaction"] = new_transaction(
            args.kind, from_ver, to_ver, rollback_to,
            args.previous_stable_before, _parse_policy(args.policy))
        save_state(state_dir, state)
        print(json.dumps({"ok": True, "phase": PHASE_PREPARED,
                          "transaction_id": state["transaction"]["transaction_id"]},
                         ensure_ascii=False))
    return EXIT_OK


def _parse_policy(raw):
    if not raw:
        return {}
    try:
        return json.loads(raw)
    except ValueError as exc:
        raise OtaError("--policy 不是合法 JSON：%s" % exc, EXIT_USAGE)


def cmd_arm_switch(args, root, state_dir):
    """PREPARED -> SWITCH_PENDING：先把切换意图落盘，之后才允许翻指针。"""
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        require_tx(state, PHASE_PREPARED)
        tx = state["transaction"]
        if read_current(root) != tx["from_version"]:
            raise ConflictError("PREPARED 阶段 current 已非原版本，拒绝推进")
        set_phase(state, PHASE_SWITCH_PENDING)
        save_state(state_dir, state)
        print(json.dumps({"ok": True, "phase": PHASE_SWITCH_PENDING}, ensure_ascii=False))
    return EXIT_OK


def cmd_do_switch(args, root, state_dir):
    """SWITCH_PENDING -> 翻转 current -> TRIAL。幂等。"""
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        require_tx(state, PHASE_SWITCH_PENDING, PHASE_TRIAL)
        tx = state["transaction"]
        flipped = switch_current(root, tx["to_version"])
        warnings = refresh_compat_links(root)
        if tx["phase"] == PHASE_SWITCH_PENDING:
            set_phase(state, PHASE_TRIAL)
            save_state(state_dir, state)
        print(json.dumps({"ok": True, "phase": tx["phase"], "flipped": flipped,
                          "warnings": warnings}, ensure_ascii=False))
    return EXIT_OK


def cmd_commit(args, root, state_dir):
    """TRIAL -> COMMITTED（或 --forced 时 FORCED_COMMITTED）。

    稳定版本元数据与 phase 在**同一次写入**中更新，避免出现
    「phase=COMMITTED 但 stable_version 还是旧的」的中间态。
    """
    forced = args.forced
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        if forced:
            require_tx(state, PHASE_TRIAL, PHASE_PREPARED, PHASE_SWITCH_PENDING)
        else:
            require_tx(state, PHASE_TRIAL)
        tx = state["transaction"]

        cur = read_current(root)
        if cur != tx["to_version"]:
            raise ConflictError(
                "提交时 current=%r 与候选版本 %s 不符，拒绝提交" % (cur, tx["to_version"]))

        # 同一次 save 里完成：phase + stable/previous 元数据
        state["previous_stable_version"] = tx["from_version"]
        state["stable_version"] = tx["to_version"]
        set_phase(state, PHASE_FORCED_COMMITTED if forced else PHASE_COMMITTED)
        save_state(state_dir, state)

        warnings = project_views(root, state)
        print(json.dumps({"ok": True, "phase": state["transaction"]["phase"],
                          "stable_version": state["stable_version"],
                          "previous_stable_version": state["previous_stable_version"],
                          "warnings": warnings}, ensure_ascii=False))
    return EXIT_OK


def cmd_abort(args, root, state_dir):
    """PREPARED / SWITCH_PENDING -> ABORTED（不触碰稳定版本）。"""
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        require_tx(state, PHASE_PREPARED, PHASE_SWITCH_PENDING)
        tx = state["transaction"]
        cur = read_current(root)
        if cur != tx["from_version"]:
            raise ConflictError(
                "中止要求 current 仍为原版本 %s，实际 %r" % (tx["from_version"], cur))
        set_phase(state, PHASE_ABORTED, error=args.reason or "aborted")
        save_state(state_dir, state)
        project_views(root, state)
        print(json.dumps({"ok": True, "phase": PHASE_ABORTED}, ensure_ascii=False))
    return EXIT_OK


def cmd_rollback_arm(args, root, state_dir):
    """TRIAL / SWITCH_PENDING -> ROLLBACK_PENDING：先记意图，再翻指针。"""
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        require_tx(state, PHASE_TRIAL, PHASE_SWITCH_PENDING)
        tx = state["transaction"]
        if tx["rollback_target"] == tx["to_version"]:
            raise ConflictError("回滚目标等于候选版本，状态非法")
        set_phase(state, PHASE_ROLLBACK_PENDING, error=args.reason or "rollback requested")
        save_state(state_dir, state)
        print(json.dumps({"ok": True, "phase": PHASE_ROLLBACK_PENDING,
                          "rollback_target": tx["rollback_target"]}, ensure_ascii=False))
    return EXIT_OK


def cmd_rollback_do(args, root, state_dir):
    """ROLLBACK_PENDING -> 翻回 rollback_target -> ROLLBACK_VERIFY。幂等。"""
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        require_tx(state, PHASE_ROLLBACK_PENDING, PHASE_ROLLBACK_VERIFY)
        tx = state["transaction"]
        flipped = switch_current(root, tx["rollback_target"])
        warnings = refresh_compat_links(root)
        if tx["phase"] == PHASE_ROLLBACK_PENDING:
            set_phase(state, PHASE_ROLLBACK_VERIFY)
            save_state(state_dir, state)
        print(json.dumps({"ok": True, "phase": tx["phase"], "flipped": flipped,
                          "warnings": warnings}, ensure_ascii=False))
    return EXIT_OK


def cmd_rolled_back(args, root, state_dir):
    """ROLLBACK_VERIFY -> ROLLED_BACK（旧版已验证健康）。

    关键：**绝不**把失败候选写进 previous_stable —— 失败版本不得因为回滚
    动作而重新获得稳定版本身份。
    """
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        require_tx(state, PHASE_ROLLBACK_VERIFY)
        tx = state["transaction"]
        if read_current(root) != tx["rollback_target"]:
            raise ConflictError("回滚目标未就位，拒绝标记 ROLLED_BACK")

        state["stable_version"] = tx["rollback_target"]
        state["previous_stable_version"] = tx["previous_stable_before"]
        set_phase(state, PHASE_ROLLED_BACK)
        save_state(state_dir, state)
        project_views(root, state)
        print(json.dumps({"ok": True, "phase": PHASE_ROLLED_BACK,
                          "stable_version": state["stable_version"],
                          "previous_stable_version": state["previous_stable_version"]},
                         ensure_ascii=False))
    return EXIT_OK


def cmd_require_recovery(args, root, state_dir):
    """任意非终态 -> RECOVERY_REQUIRED（停止一切自动动作）。"""
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        tx = tx_of(state)
        if tx is None:
            raise ConflictError("没有进行中的事务")
        if tx["phase"] == PHASE_RECOVERY_REQUIRED:
            print(json.dumps({"ok": True, "phase": PHASE_RECOVERY_REQUIRED,
                              "note": "已是 RECOVERY_REQUIRED"}, ensure_ascii=False))
            return EXIT_OK
        set_phase(state, PHASE_RECOVERY_REQUIRED, error=args.reason or "recovery required")
        save_state(state_dir, state)
        print(json.dumps({"ok": True, "phase": PHASE_RECOVERY_REQUIRED}, ensure_ascii=False))
    return EXIT_OK


def cmd_recover(args, root, state_dir):
    """RECOVERY_REQUIRED 的人工退出通道。

    运维修复现场后必须显式指定一个可信版本（--accept）或显式放弃（--abort），
    不允许"自动恢复"——那样会把未验证的猜测写回权威状态。
    """
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        tx = tx_of(state)
        if tx is None or tx["phase"] != PHASE_RECOVERY_REQUIRED:
            raise ConflictError("当前不处于 RECOVERY_REQUIRED")

        if args.abort:
            set_phase(state, PHASE_ABORTED, error="manual abort from recovery")
            save_state(state_dir, state)
            project_views(root, state)
            print(json.dumps({"ok": True, "phase": PHASE_ABORTED}, ensure_ascii=False))
            return EXIT_OK

        if not args.accept:
            raise OtaError("必须指定 --accept <version> 或 --abort", EXIT_USAGE)

        accepted = check_version(args.accept, "--accept")
        if not release_exists(root, accepted):
            raise OtaError("指定版本不存在：releases/%s" % accepted, EXIT_USAGE)

        switch_current(root, accepted)
        warnings = refresh_compat_links(root)
        state["stable_version"] = accepted
        state["previous_stable_version"] = tx.get("previous_stable_before")
        set_phase(state, PHASE_COMMITTED, error="manual recovery accepted %s" % accepted)
        save_state(state_dir, state)
        warnings += project_views(root, state)
        print(json.dumps({"ok": True, "phase": PHASE_COMMITTED,
                          "stable_version": accepted, "warnings": warnings},
                         ensure_ascii=False))
    return EXIT_OK


def cmd_reconcile(args, root, state_dir):
    state = load_state(state_dir)
    verdict = reconcile(root, state)
    if args.dry_run:
        verdict["dry_run"] = True
        print(json.dumps(verdict, ensure_ascii=False, indent=2, sort_keys=True))
        return EXIT_RECOVERY if verdict["action"] == "recovery_required" else EXIT_OK

    # 非 dry-run：只执行 reconcile 判定为安全的自动动作
    action = verdict["action"]
    if action in ("none", "recovery_required"):
        print(json.dumps(verdict, ensure_ascii=False, indent=2, sort_keys=True))
        return EXIT_RECOVERY if action == "recovery_required" else EXIT_OK

    argv = [sys.executable, os.path.abspath(__file__)]
    argv += ["--root", root, "--state-dir", state_dir]
    if action == "abort":
        argv += ["abort", "--reason", verdict["reason"]]
    elif action == "mark_trial":
        argv += ["do-switch"]
    elif action == "project_views":
        argv += ["project-views"]
    else:
        # continue_trial / continue_rollback 需要健康判定，属 P0-B 职责
        print(json.dumps(verdict, ensure_ascii=False, indent=2, sort_keys=True))
        return EXIT_OK
    os.execv(sys.executable, argv)


def cmd_project_views(args, root, state_dir):
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        warnings = project_views(root, state)
        print(json.dumps({"ok": True, "warnings": warnings}, ensure_ascii=False))
    return EXIT_OK


def cmd_gc(args, root, state_dir):
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        removed, skip_reason = collect_garbage(root, state, args.max_keep)
        print(json.dumps({"ok": True, "removed": removed, "skipped": skip_reason},
                         ensure_ascii=False))
    return EXIT_OK


def cmd_bootstrap(args, root, state_dir):
    """老设备首次接管：从现有布局推断稳定版本并建立 schema v1 记录。

    推断规则严格：current 指向的 release 必须存在且带 `.committed`；
    否则拒绝自动推断，要求人工指定 `--accept-stable`。
    """
    with ExclusiveLock(state_dir):
        if os.path.exists(state_path(state_dir)) and not args.force:
            raise ConflictError("事务状态已存在，bootstrap 拒绝覆盖（需 --force）")

        cur = read_current(root)
        if cur is None:
            raise OtaError("current 软链不存在或形态异常，无法自动推断稳定版本", EXIT_USAGE)

        marker = os.path.join(release_dir(root, cur), ".committed")
        if not os.path.exists(marker):
            if not args.accept_stable:
                raise OtaError(
                    "current=%s 缺少 .committed，无法确认它是已转正版本；"
                    "请人工确认后用 --accept-stable <version>" % cur, EXIT_RECOVERY)
            cur = check_version(args.accept_stable, "--accept-stable")

        prev_file = os.path.join(root, "releases", ".previous")
        prev = None
        if os.path.exists(prev_file):
            with open(prev_file, "r", encoding="utf-8") as fh:
                candidate = fh.read().strip()
            if VERSION_RE.match(candidate) and release_exists(root, candidate) and candidate != cur:
                prev = candidate

        state = empty_state()
        state["stable_version"] = cur
        state["previous_stable_version"] = prev

        if args.dry_run:
            print(json.dumps({"dry_run": True, "stable_version": cur,
                              "previous_stable_version": prev,
                              "current": read_current(root)}, ensure_ascii=False, indent=2))
            return EXIT_OK

        save_state(state_dir, state)
        warnings = project_views(root, state)
        print(json.dumps({"ok": True, "stable_version": cur,
                          "previous_stable_version": prev, "warnings": warnings},
                         ensure_ascii=False))
    return EXIT_OK


def cmd_bump_boot_attempt(args, root, state_dir):
    """P0-B 用：每次**实际启动试运行前**先原子加一，防止断电无限重试。

    必须在启动之前调用——先启动再计数的话，掉电会漏计。
    """
    with ExclusiveLock(state_dir):
        state = load_state(state_dir)
        require_tx(state, PHASE_TRIAL)
        tx = state["transaction"]
        tx["boot_attempts"] = int(tx["boot_attempts"]) + 1
        if args.boot_id:
            tx["last_trial_boot_id"] = args.boot_id
        save_state(state_dir, state)
        print(json.dumps({"ok": True, "boot_attempts": tx["boot_attempts"]},
                         ensure_ascii=False))
    return EXIT_OK


# ============================================================================
# CLI
# ============================================================================

def build_parser():
    parser = argparse.ArgumentParser(
        prog="weaknet-ota-ctl",
        description="WeakNet OTA 升级事务控制器（P0-A）：唯一的版本指针与事务状态写入口")
    parser.add_argument("--root", default=None, help="weaknet 安装根（默认 $WEAKNET_ROOT 或 /home/radxa/weaknet）")
    parser.add_argument("--state-dir", default=None, help="事务状态目录（默认 /var/lib/weaknet-ota）")

    sub = parser.add_subparsers(dest="command", required=True)

    sub.add_parser("status", help="输出当前状态（JSON）")

    p = sub.add_parser("begin", help="开始一笔事务（PREPARED）")
    p.add_argument("--kind", default="upgrade", choices=["upgrade", "manual_rollback"])
    p.add_argument("--from", dest="from_version", required=True)
    p.add_argument("--to", dest="to_version", required=True)
    p.add_argument("--rollback-target", required=True)
    p.add_argument("--previous-stable-before", default=None)
    p.add_argument("--policy", default=None, help="JSON 字符串，快照保存")

    sub.add_parser("arm-switch", help="PREPARED -> SWITCH_PENDING（落盘切换意图）")
    sub.add_parser("do-switch", help="SWITCH_PENDING -> 翻 current -> TRIAL（幂等）")

    p = sub.add_parser("commit", help="TRIAL -> COMMITTED")
    p.add_argument("--forced", action="store_true",
                   help="跳过健康验证直接提交（对应 --commit），落 FORCED_COMMITTED")

    p = sub.add_parser("abort", help="PREPARED/SWITCH_PENDING -> ABORTED")
    p.add_argument("--reason", default=None)

    p = sub.add_parser("rollback-arm", help="TRIAL/SWITCH_PENDING -> ROLLBACK_PENDING")
    p.add_argument("--reason", default=None)
    sub.add_parser("rollback-do", help="ROLLBACK_PENDING -> 翻回 -> ROLLBACK_VERIFY（幂等）")
    sub.add_parser("rolled-back", help="ROLLBACK_VERIFY -> ROLLED_BACK")

    p = sub.add_parser("require-recovery", help="进入 RECOVERY_REQUIRED（停止自动动作）")
    p.add_argument("--reason", default=None)

    p = sub.add_parser("recover", help="人工退出 RECOVERY_REQUIRED")
    p.add_argument("--accept", default=None, help="认定该版本为稳定版本并切到它")
    p.add_argument("--abort", action="store_true", help="放弃本事务")

    p = sub.add_parser("reconcile", help="按持久事实判定下一步")
    p.add_argument("--dry-run", action="store_true", help="只输出判定，不执行")

    sub.add_parser("project-views", help="重建 .committed / .previous 兼容视图")

    p = sub.add_parser("gc", help="保守回收历史版本")
    p.add_argument("--max-keep", type=int, default=3)

    p = sub.add_parser("bootstrap", help="老设备首次接管")
    p.add_argument("--dry-run", action="store_true")
    p.add_argument("--force", action="store_true")
    p.add_argument("--accept-stable", default=None)

    p = sub.add_parser("bump-boot-attempt", help="P0-B：启动试运行前先加一")
    p.add_argument("--boot-id", default=None)

    return parser


HANDLERS = {
    "status": cmd_status,
    "begin": cmd_begin,
    "arm-switch": cmd_arm_switch,
    "do-switch": cmd_do_switch,
    "commit": cmd_commit,
    "abort": cmd_abort,
    "rollback-arm": cmd_rollback_arm,
    "rollback-do": cmd_rollback_do,
    "rolled-back": cmd_rolled_back,
    "require-recovery": cmd_require_recovery,
    "recover": cmd_recover,
    "reconcile": cmd_reconcile,
    "project-views": cmd_project_views,
    "gc": cmd_gc,
    "bootstrap": cmd_bootstrap,
    "bump-boot-attempt": cmd_bump_boot_attempt,
}


def main(argv=None):
    parser = build_parser()
    args = parser.parse_args(argv)
    root, state_dir = resolve_paths(args.root, args.state_dir)
    try:
        return HANDLERS[args.command](args, root, state_dir)
    except OtaError as exc:
        sys.stderr.write("weaknet-ota-ctl: %s\n" % exc)
        return exc.code


if __name__ == "__main__":
    sys.exit(main())

